  "title": "De R$ 80 para R$ 100 no Python",
  "problem": "Um ingresso passou de R$ 80 para R$ 100. Qual foi a variação percentual?",
  "steps": [
    {
      "text": "Guarde os preços em variáveis.",
      "math": "`antigo = 80\\nnovo = 100`"
    },
    {
      "text": "Calcule quanto o preço variou.",
      "math": "`variacao = novo - antigo`"
    },
    {
      "text": "Divida a variação pelo preço inicial.",
      "math": "`fracao = variacao / antigo`"
    },
    {
      "text": "Converta para porcentagem e mostre o resultado.",
      "math": "`percentual = fracao * 100\\nprint(percentual)  # 25.0`"
    }
  ],
  "result": "O preço subiu 25%.",
